      "resultsSection": {
        "participantFlowModule": {
          "preAssignmentDetails": "A total of 16436 participants were screened, of whom 1606 participants were screen failures. 14830 of the screened participants were randomized to treatment and 14757 participants were treated. 73 participants never received study intervention.",
