              "description": "Participants received asundexian 50 mg once a day (OD) and apixaban matching placebo."
            },
            {
              "id": "FG001",
              "title": "Apixaban",
              "description": "Participants received apixaban 5 mg twice a day (BID) or reduced dose 2.5 mg BID and asundexian matching placebo."
            }
          ],
